def choose(sub, design):
    states = sub["states"]

    is_write = False
    for term in sub["case_terms"]:
        if term["field"] == "rd" and term["op"] == "==":
            is_write = True

    is_pc = "pc" in states
    need_icache = is_write or is_pc

    ops = []
    for c in design["choices"]:
        if c["kind"] == "operator":
