            inst = c.get("instance", "")
            parts = inst.split(".")
            last = parts[len(parts) - 1]
            if last == "icache":
                if need_icache:
                    result[cid] = "keep"
                else:
                    result[cid] = "cut"
            else:
                result[cid] = "cut"
        elif kind == "gpr":
            result[cid] = choose_gpr_level(c["register"], sub, design)
