def tokens_ident(text):
    s = text.lower()
    for ch in [".", "_", "$", "[", "]", "(", ")", ":", "/", "\\", "-", ">", "<",
               "=", "+", "*", "{", "}", " ", "\t", "\n", ",", ";"]:
