    return best_id


def choose(sub, design):
    kind = instr_kind(design)
    write_reg = effective_write_reg(sub)

    state_regs = set()
    for s in sub.get("states", []):
        if s.startswith("x") and s[1:].isdigit():
            state_regs.add(int(s[1:]))

    relevant_gprs = set(state_regs)
    if needs_sources(kind, sub, write_reg):
        for term in sub.get("case_terms", []):
            if term.get("op") == "==" and term.get("field") in design.get("operand_fields", []):
                relevant_gprs.add(term.get("value"))

    need_dcache = (kind == "load" and write_reg is not None and write_reg != 0)
    need_icache = has_state(sub, "pc")

    selected_operator = choose_operator(design, sub, kind, write_reg)

    levels = {}
    for ch in design.get("choices", []):
        cid = ch.get("id", "")
        ckind = ch.get("kind", "")
        if ckind == "unit":
            levels[cid] = unit_level(ch, kind, need_dcache, need_icache)
        elif ckind == "gpr":
            r = ch.get("register")
            levels[cid] = "keep" if r in relevant_gprs else "havoc"
        elif ckind == "operator":
            levels[cid] = "uf" if cid == selected_operator else "keep"
    return levels
